"""
uifont.py: the Inter typeface (SIL Open Font License), built into the desktop apps so their
text looks the same, and reads clearly, on every computer. Made from site/*.woff.
"""

FONT_CSS = '@font-face{font-family:"Inter NG";src:url(data:font/woff;base64,) format("woff");font-weight:400;font-display:block}@font-face{font-family:"Inter NG";src:url(data:font/woff;base64,) format("woff");font-weight:600;font-display:block}@font-face{font-family:"Inter NG Display";src:url(data:font/woff;base64,) format("woff");font-weight:700;font-display:block}'


def with_font(page):
    """The page with the font added to its first <style>."""
    return page.replace("<style>", "<style>" + FONT_CSS, 1)
